module x_oracle::price_feed;

// We fix the number of price decimals to 9
const PRICE_DECIMALS: u8 = 9;

public struct PriceFeedComponent has copy, drop, store {
    value: u64,
    update_time: u64,
}

public struct PriceFeed has copy, drop, store {
    spot: PriceFeedComponent,
    ema: Option<PriceFeedComponent>,
    // reserved field for future twap price feed upgrades, currently not used
    twap: Option<PriceFeedComponent>,
}

public(package) fun new(spot: PriceFeedComponent, ema: PriceFeedComponent): PriceFeed {
    PriceFeed { spot, ema: std::option::some(ema), twap: std::option::none() }
}

public(package) fun new_component(value: u64, update_time: u64): PriceFeedComponent {
    PriceFeedComponent { value, update_time }
}

public(package) fun set(self: &mut PriceFeed, spot: PriceFeedComponent, ema: PriceFeedComponent) { 
    self.ema = std::option::some(ema);
    self.spot = spot;
}

public fun ema(self: &PriceFeed): &PriceFeedComponent { self.ema.borrow() }
public fun spot(self: &PriceFeed): &PriceFeedComponent { &self.spot }
public fun value(self: &PriceFeedComponent): u64 { self.value }
public fun update_time(self: &PriceFeedComponent): u64 { self.update_time }

/// Normalize price to this decimal places
public fun decimals(): u8 { PRICE_DECIMALS }

/// @title A module dedicated for handling the borrow request from user
module protocol::borrow;

use std::type_name::{Self, TypeName};
use sui::clock::{Self, Clock};
use sui::coin::{Self, Coin};
use sui::event::emit;

use math::float::Decimal;

use x_oracle::x_oracle::XOracle;

use protocol::coin_decimals_registry::CoinDecimalsRegistry;
use protocol::market::Market;
use protocol::obligation::ObligationOwnerCap;
use protocol::liquidity_miner::get_borrow_reward_type;
use protocol::app::ProtocolApp;

public struct BorrowEvent has copy, drop {
    borrower: address,

    market: TypeName,
    obligation: ID,

    asset: TypeName,

    amount: u64,
    total_borrow: Decimal,
    borrow_index: Decimal,

    time: u64,
}

public fun borrow<MarketType, CoinType>(
    app: &ProtocolApp,
    obligation_owner_cap: &ObligationOwnerCap,
    market: &mut Market<MarketType>,
    coin_decimals_registry: &CoinDecimalsRegistry,
    borrow_amount: u64,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
): Coin<CoinType> {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let now = clock::timestamp_ms(clock) / 1000;

    let (borrowed_balance, borrow_index, total_borrow) = market.handle_borrow(
        obligation_owner_cap.id(),
        borrow_amount,
        coin_decimals_registry,
        x_oracle,
        clock,
        now
    );

    let miner = market.borrow_liquidity_mining_mut<MarketType>();
    miner.update_obligation_reward_manager<MarketType, CoinType>(
        get_borrow_reward_type(),
        obligation_owner_cap.id(),
        total_borrow.floor(),
        clock
    );

    // Emit the borrow event
    emit(BorrowEvent {
        borrower: ctx.sender(),

        market: type_name::with_defining_ids<MarketType>(),
        obligation: obligation_owner_cap.id(),

        asset: type_name::with_defining_ids<CoinType>(),
        amount: borrow_amount,

        total_borrow,
        borrow_index,

        time: now,
    });

    coin::from_balance(borrowed_balance, ctx)
}

